package br.com.brindespro.common;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {public record Error(String message){}@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Error> badRequest(IllegalArgumentException e){return ResponseEntity.badRequest().body(new Error(e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Error> invalid(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(new Error(e.getBindingResult().getFieldErrors().stream().findFirst().map(v->v.getField()+": "+v.getDefaultMessage()).orElse("Dados inválidos.")));}}
